@@preprocessing
<%_ {
const data=getMessageVar('stat_data',{defaults:{}}),world=_.get(data,'世界',{}),events=_.get(world,'事件',{}),organizations=_.get(world,'組織',{});
const floor=Math.max(1,Math.min(100,Number(_.get(world,'當前樓層',1))||1)),unlocked=(_.get(world,'已解鎖樓層',[])||[]).map(Number).filter(Number.isFinite),frontier=Math.max(floor,...unlocked,1);
const eventFlags=Object.values(events).reduce((out,event)=>Object.assign(out,event?.旗標||{}),{});
const guildQuest=eventFlags['第三層公會任務完成']===true||eventFlags['公會登記解鎖']===true;
const floor1Boss=eventFlags['首層Boss已討伐']===true||_.get(world,'樓層檔案.1.Boss討伐',false)===true;
const knownLocations=Object.values(_.get(world,'樓層檔案',{})).reduce((sum,file)=>sum+(Array.isArray(file?.已確認地點)?file.已確認地點.length:0),0);
const knownOrgs=Object.values(organizations).filter(org=>org&&!['解散','覆滅','合併','消失'].includes(String(org.狀態||''))).length;
const stage=!floor1Boss?'開服混亂期':!guildQuest?'攻略協作形成期':frontier<10?'公會制度初成期':frontier<25?'中層拓展期':frontier<50?'組織重整期':'高層攻略期';
const ability={階段名稱:stage,攻略前線:frontier,正式公會登記:guildQuest,攻略集團公開活動:floor1Boss,跨聚落穩定市場:frontier>=2&&knownLocations>=4,廣域情報網路:frontier>=5&&knownLocations>=10,高層內容公開:frontier>=10,判定依據:{已確認地點數:knownLocations,活動組織數:knownOrgs}};
_%>
<SAO_ERA_GATE version="5.1.1">
當前時代能力：<%- JSON.stringify(ability) %>
正式公會登記只由第三層公會任務或明確開局旗標解鎖。原作組織、制度、市場、情報與任務密度必須滿足各自門檻。靜態條目被注入不代表已成立、已發生、已被玩家得知或已接取。所有成立事件寫入`/世界/事件`，組織寫入`/世界/組織`。
</SAO_ERA_GATE>
<%_ } _%>

